 sealed class LauncherLandscape:Panel {
  public LauncherTheme Palette;public LauncherLandscape(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Palette==null||Width<1||Height<1)return;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;int w=Width,h=Height;
   using(var gradient=new LinearGradientBrush(ClientRectangle,Palette.Light?Color.FromArgb(189,216,241):Color.FromArgb(48,62,60),Palette.Background,90f))g.FillRectangle(gradient,ClientRectangle);
   using(var grid=new Pen(Color.FromArgb(25,Palette.Accent),1)){for(int x=-h;x<w+h;x+=60)g.DrawLine(grid,x,0,x+h,h);for(int x=0;x<w+h;x+=60)g.DrawLine(grid,x,0,x-h,h);}
   var road=new[]{new Point(w*2/3,-20),new Point(w/2,h/3),new Point(w*3/4,h*2/3),new Point(w/2,h+20)};using(var p=new Pen(Color.FromArgb(65,Palette.Muted),42)){p.LineJoin=LineJoin.Round;g.DrawLines(p,road);}using(var p=new Pen(Color.FromArgb(110,Palette.Accent),1)){p.DashStyle=DashStyle.Dash;g.DrawLines(p,road);}
   var random=new Random(108600);for(int i=0;i<80;i++){int x=random.Next(w),y=random.Next(h);if(x<w/3)continue;int s=random.Next(9,32);using(var b=new SolidBrush(Color.FromArgb(Palette.Light?65:95,i%3==0?Palette.Accent:Palette.Muted)))g.FillPolygon(b,new[]{new Point(x,y-s),new Point(x+s,y-s/2),new Point(x,y),new Point(x-s,y-s/2)});}
   using(var b=new SolidBrush(Color.FromArgb(Palette.Light?170:205,Palette.Background)))g.FillRectangle(b,0,h*2/3,w,h/3);
  }
 }
