  void ApplyLauncherTheme(bool light,bool persist){launcherTheme=LauncherTheme.Create(light);bg=launcherTheme.Background;card=launcherTheme.Surface;fg=launcherTheme.Text;Theme(this);progress.BackColor=card;progress.ForeColor=launcherTheme.Accent;progress.Invalidate();launcherHome.Palette=launcherTheme;launcherHome.Invalidate();launcherThemeButton.Text=light?"切换：深金主题":"切换：浅蓝主题";launcherLaunch.BackColor=launcherTheme.Accent;launcherLaunch.ForeColor=light?Color.White:Color.FromArgb(30,29,25);RefreshLauncherNavigation();if(persist)launcherTheme.Save(data);}
